#include <iostream>
using namespace std;

int main() {
    long long aa, k, l, ttl = 0;
    cin >> aa;
    for (long long i = 2; i < aa; ++i) {
        k = aa;
        while (k > 0) {
            ttl += (k % i);
            k /= i;
            if (k < i) {
                ttl += k;
                break;
            }
        }
    }
    l = aa - 2;
    for (long long i = l; i > 1; --i) {
        if (ttl % i == 0 && l % i == 0) {
            ttl /= i;
            l /= i;
            break;
        }
    }
    cout << ttl << "/" << l << endl;
    return 0;
}

